import java.util.Scanner;

public class Main {
    static final int MAX = 500;
    static int[][] comb = new int[MAX + 1][MAX + 1];
    static long[][][] dpA = new long[MAX + 1][2]; // Using long for pair-like storage
    static long[][][][] dpB = new long[2][MAX + 1][MAX + 1][2]; // 4D array to store pairs

    static int modulus;

    static void update(long[] x, long y) {
        x[0] += y;
        if (x[0] >= modulus) x[0] -= modulus;
    }

    static long total_sum(int n) {
        return (long) n * (n + 1) >> 1;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        modulus = sc.nextInt();

        for (int i = 0; i <= m; i++) {
            comb[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                comb[i][j] = comb[i - 1][j - 1] + comb[i - 1][j];
                if (comb[i][j] >= modulus) comb[i][j] -= modulus;
            }
        }

        // Initialize dpA
        dpA[0][0] = 1; // first element
        for (int i = 1; i <= m; i++) {
            long first = 0;
            long second = 0;
            for (int j = 1; j <= i; j++) {
                long w = ((long) dpA[j - 1][0] * dpA[i - j][0]) % modulus;
                w = (w * comb[i - 1][j - 1]) % modulus;

                long totalSum = (total_sum(j - 1) + total_sum(i - j)) % modulus;
                long term1 = (totalSum * w) % modulus;

                long term2 = (((dpA[j - 1][1] * dpA[i - j][0]) % modulus) * (i + 1)) % modulus;
                term2 = (term2 * comb[i - 1][j - 1]) % modulus;

                long term3 = (((dpA[j - 1][0] * dpA[i - j][1]) % modulus) * (i + 1)) % modulus;
                term3 = (term3 * comb[i - 1][j - 1]) % modulus;

                update(new long[]{second}, term1);
                update(new long[]{second}, term2);
                update(new long[]{second}, term3);
                update(new long[]{first}, (w * (i + 1)) % modulus);
            }
            dpA[i][0] = first;
            dpA[i][1] = second;
        }

        // Initialize dpB
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                dpB[0][i][j][0] = 0;
                dpB[0][i][j][1] = 0;
                dpB[1][i][j][0] = 0;
                dpB[1][i][j][1] = 0;
            }
        }
        dpB[0][0][0][0] = 1;
        dpB[1][0][0][0] = 1;

        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= i; j++) {
                for (int ln = 1; ln <= n - i; ln++) {
                    // Update dpB[1]
                    update(new long[]{dpB[1][i + ln][j]}, dpB[0][i][j][0]);
                    update(new long[]{dpB[1][i + ln][j]}, dpB[0][i][j][1]);

                    // Update dpB[0]
                    long val1 = (dpB[1][i][j][0] * dpA[ln][0]) % modulus;
                    val1 = (val1 * comb[j + ln][j]) % modulus;
                    update(new long[]{dpB[0][i + ln][j + ln][0]}, val1);

                    long val2 = (dpB[1][i][j][0] * dpA[ln][1]) % modulus;
                    val2 = (val2 * comb[j + ln][j]) % modulus;
                    update(new long[]{dpB[0][i + ln][j + ln][1]}, val2);

                    long val3 = (dpB[1][i][j][1] * dpA[ln][0]) % modulus;
                    val3 = (val3 * comb[j + ln][j]) % modulus;
                    update(new long[]{dpB[0][i + ln][j + ln][1]}, val3);
                }
            }
        }

        long result = dpB[0][n][m][1];
        result = (result + dpB[1][n][m][1]) % modulus;
        System.out.println(result);
        sc.close();
    }

    static void update(long[] x, long y) {
        x[0] += y;
        if (x[0] >= modulus) x[0] -= modulus;
    }
}
